macro_rules! deps {
    () => {
        GroupInfoInner!();
        NFA!();
        PatternID!();
        Slots!();
        Captures!();
    };
}

macro_rules! GroupInfo {
    () => {
        deps!();
        # [doc = " Represents information about capturing groups in a compiled regex."] # [doc = ""] # [doc = " The information encapsulated by this type consists of the following. For"] # [doc = " each pattern:"] # [doc = ""] # [doc = " * A map from every capture group name to its corresponding capture group"] # [doc = " index."] # [doc = " * A map from every capture group index to its corresponding capture group"] # [doc = " name."] # [doc = " * A map from capture group index to its corresponding slot index. A slot"] # [doc = " refers to one half of a capturing group. That is, a capture slot is either"] # [doc = " the start or end of a capturing group. A slot is usually the mechanism"] # [doc = " by which a regex engine records offsets for each capturing group during a"] # [doc = " search."] # [doc = ""] # [doc = " A `GroupInfo` uses reference counting internally and is thus cheap to"] # [doc = " clone."] # [doc = ""] # [doc = " # Mapping from capture groups to slots"] # [doc = ""] # [doc = " One of the main responsibilities of a `GroupInfo` is to build a mapping"] # [doc = " from `(PatternID, u32)` (where the `u32` is a capture index) to something"] # [doc = " called a \"slot.\" As mentioned above, a slot refers to one half of a"] # [doc = " capturing group. Both combined provide the start and end offsets of"] # [doc = " a capturing group that participated in a match."] # [doc = ""] # [doc = " **The mapping between group indices and slots is an API guarantee.** That"] # [doc = " is, the mapping won't change within a semver compatible release."] # [doc = ""] # [doc = " Slots exist primarily because this is a convenient mechanism by which"] # [doc = " regex engines report group offsets at search time. For example, the"] # [doc = " [`nfa::thompson::State::Capture`](crate::nfa::thompson::State::Capture)"] # [doc = " NFA state includes the slot index. When a regex engine transitions through"] # [doc = " this state, it will likely use the slot index to write the current haystack"] # [doc = " offset to some region of memory. When a match is found, those slots are"] # [doc = " then reported to the caller, typically via a convenient abstraction like a"] # [doc = " [`Captures`] value."] # [doc = ""] # [doc = " Because this crate provides first class support for multi-pattern regexes,"] # [doc = " and because of some performance related reasons, the mapping between"] # [doc = " capturing groups and slots is a little complex. However, in the case of a"] # [doc = " single pattern, the mapping can be described very simply: for all capture"] # [doc = " group indices `i`, its corresponding slots are at `i * 2` and `i * 2 + 1`."] # [doc = " Notice that the pattern ID isn't involved at all here, because it only"] # [doc = " applies to a single-pattern regex, it is therefore always `0`."] # [doc = ""] # [doc = " In the multi-pattern case, the mapping is a bit more complicated. To talk"] # [doc = " about it, we must define what we mean by \"implicit\" vs \"explicit\""] # [doc = " capturing groups:"] # [doc = ""] # [doc = " * An **implicit** capturing group refers to the capturing group that is"] # [doc = " present for every pattern automatically, and corresponds to the overall"] # [doc = " match of a pattern. Every pattern has precisely one implicit capturing"] # [doc = " group. It is always unnamed and it always corresponds to the capture group"] # [doc = " index `0`."] # [doc = " * An **explicit** capturing group refers to any capturing group that"] # [doc = " appears in the concrete syntax of the pattern. (Or, if an NFA was hand"] # [doc = " built without any concrete syntax, it refers to any capturing group with an"] # [doc = " index greater than `0`.)"] # [doc = ""] # [doc = " Some examples:"] # [doc = ""] # [doc = " * `\\w+` has one implicit capturing group and zero explicit capturing"] # [doc = " groups."] # [doc = " * `(\\w+)` has one implicit group and one explicit group."] # [doc = " * `foo(\\d+)(?:\\pL+)(\\d+)` has one implicit group and two explicit groups."] # [doc = ""] # [doc = " Turning back to the slot mapping, we can now state it as follows:"] # [doc = ""] # [doc = " * Given a pattern ID `pid`, the slots for its implicit group are always"] # [doc = " at `pid * 2` and `pid * 2 + 1`."] # [doc = " * Given a pattern ID `0`, the slots for its explicit groups start"] # [doc = " at `group_info.pattern_len() * 2`."] # [doc = " * Given a pattern ID `pid > 0`, the slots for its explicit groups start"] # [doc = " immediately following where the slots for the explicit groups of `pid - 1`"] # [doc = " end."] # [doc = ""] # [doc = " In particular, while there is a concrete formula one can use to determine"] # [doc = " where the slots for the implicit group of any pattern are, there is no"] # [doc = " general formula for determining where the slots for explicit capturing"] # [doc = " groups are. This is because each pattern can contain a different number"] # [doc = " of groups."] # [doc = ""] # [doc = " The intended way of getting the slots for a particular capturing group"] # [doc = " (whether implicit or explicit) is via the [`GroupInfo::slot`] or"] # [doc = " [`GroupInfo::slots`] method."] # [doc = ""] # [doc = " See below for a concrete example of how capturing groups get mapped to"] # [doc = " slots."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to build a new `GroupInfo` and query it for"] # [doc = " information."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::util::{captures::GroupInfo, primitives::PatternID};"] # [doc = ""] # [doc = " let info = GroupInfo::new(vec!["] # [doc = "     vec![None, Some(\"foo\")],"] # [doc = "     vec![None],"] # [doc = "     vec![None, None, None, Some(\"bar\"), None],"] # [doc = "     vec![None, None, Some(\"foo\")],"] # [doc = " ])?;"] # [doc = " // The number of patterns being tracked."] # [doc = " assert_eq!(4, info.pattern_len());"] # [doc = " // We can query the number of groups for any pattern."] # [doc = " assert_eq!(2, info.group_len(PatternID::must(0)));"] # [doc = " assert_eq!(1, info.group_len(PatternID::must(1)));"] # [doc = " assert_eq!(5, info.group_len(PatternID::must(2)));"] # [doc = " assert_eq!(3, info.group_len(PatternID::must(3)));"] # [doc = " // An invalid pattern always has zero groups."] # [doc = " assert_eq!(0, info.group_len(PatternID::must(999)));"] # [doc = " // 2 slots per group"] # [doc = " assert_eq!(22, info.slot_len());"] # [doc = ""] # [doc = " // We can map a group index for a particular pattern to its name, if"] # [doc = " // one exists."] # [doc = " assert_eq!(Some(\"foo\"), info.to_name(PatternID::must(3), 2));"] # [doc = " assert_eq!(None, info.to_name(PatternID::must(2), 4));"] # [doc = " // Or map a name to its group index."] # [doc = " assert_eq!(Some(1), info.to_index(PatternID::must(0), \"foo\"));"] # [doc = " assert_eq!(Some(2), info.to_index(PatternID::must(3), \"foo\"));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: mapping from capture groups to slots"] # [doc = ""] # [doc = " This example shows the specific mapping from capture group indices for"] # [doc = " each pattern to their corresponding slots. The slot values shown in this"] # [doc = " example are considered an API guarantee."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::util::{captures::GroupInfo, primitives::PatternID};"] # [doc = ""] # [doc = " let info = GroupInfo::new(vec!["] # [doc = "     vec![None, Some(\"foo\")],"] # [doc = "     vec![None],"] # [doc = "     vec![None, None, None, Some(\"bar\"), None],"] # [doc = "     vec![None, None, Some(\"foo\")],"] # [doc = " ])?;"] # [doc = ""] # [doc = " // We first show the slots for each pattern's implicit group."] # [doc = " assert_eq!(Some((0, 1)), info.slots(PatternID::must(0), 0));"] # [doc = " assert_eq!(Some((2, 3)), info.slots(PatternID::must(1), 0));"] # [doc = " assert_eq!(Some((4, 5)), info.slots(PatternID::must(2), 0));"] # [doc = " assert_eq!(Some((6, 7)), info.slots(PatternID::must(3), 0));"] # [doc = ""] # [doc = " // And now we show the slots for each pattern's explicit group."] # [doc = " assert_eq!(Some((8, 9)), info.slots(PatternID::must(0), 1));"] # [doc = " assert_eq!(Some((10, 11)), info.slots(PatternID::must(2), 1));"] # [doc = " assert_eq!(Some((12, 13)), info.slots(PatternID::must(2), 2));"] # [doc = " assert_eq!(Some((14, 15)), info.slots(PatternID::must(2), 3));"] # [doc = " assert_eq!(Some((16, 17)), info.slots(PatternID::must(2), 4));"] # [doc = " assert_eq!(Some((18, 19)), info.slots(PatternID::must(3), 1));"] # [doc = " assert_eq!(Some((20, 21)), info.slots(PatternID::must(3), 2));"] # [doc = ""] # [doc = " // Asking for the slots for an invalid pattern ID or even for an invalid"] # [doc = " // group index for a specific pattern will return None. So for example,"] # [doc = " // you're guaranteed to not get the slots for a different pattern than the"] # [doc = " // one requested."] # [doc = " assert_eq!(None, info.slots(PatternID::must(5), 0));"] # [doc = " assert_eq!(None, info.slots(PatternID::must(1), 1));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug , Default)] pub struct GroupInfo (Arc < GroupInfoInner >) ;
    };
}

GroupInfo!()